#!/usr/bin/env node
/**
 * build-worker-bundle.js
 * 
 * Generates worker-data-bundle.js by extracting and serializing all gazetteers
 * and term data needed by the Web Worker. This ensures the Worker has all
 * necessary data pre-loaded at initialization time.
 * 
 * Strategy: Use VM context to load the global variables since they're exported to globalThis
 * 
 * Run: node scripts/build-worker-bundle.js
 * Output: worker-data-bundle.js (injected into Worker via blob)
 */

const fs = require('fs');
const path = require('path');
const vm = require('vm');

console.log('[build-worker-bundle] Loading term data...');

// Create a sandbox context to execute the term files
const sandbox = {
  globalThis: {},
  console: console
};

// Load each term file in the sandbox
const termFiles = [
  'terms-medical.js',
  'terms-financial.js',
  'terms-organizations.js',
  'terms-occupations.js'
];

for (const file of termFiles) {
  const filePath = path.join(__dirname, '..', file);
  const code = fs.readFileSync(filePath, 'utf-8');
  try {
    vm.runInNewContext(code, sandbox, { filename: file });
  } catch (err) {
    console.error(`Error loading ${file}:`, err.message);
    process.exit(1);
  }
}

// Extract the data from the sandbox
const medicalTerms = sandbox.MEDICAL_TERMS_DATA || sandbox.globalThis.MEDICAL_TERMS_DATA || [];
const financialTerms = sandbox.FINANCIAL_TERMS_DATA || sandbox.globalThis.FINANCIAL_TERMS_DATA || [];
const organizationTerms = sandbox.ORGANIZATIONS_DATA || sandbox.globalThis.ORGANIZATIONS_DATA || [];
const occupationTerms = sandbox.OCCUPATIONS_DATA || sandbox.globalThis.OCCUPATIONS_DATA || [];

console.log(`  ✓ Medical terms: ${medicalTerms.length} items`);
console.log(`  ✓ Financial terms: ${financialTerms.length} items`);
console.log(`  ✓ Organization terms: ${organizationTerms.length} items`);
console.log(`  ✓ Occupation terms: ${occupationTerms.length} items`);

// Build the bundle - use minimal compression (no spaces) to reduce file size
const bundle = `// worker-data-bundle.js
// AUTO-GENERATED by build-worker-bundle.js — DO NOT EDIT MANUALLY
// Contains all gazetteers and term data needed by the Web Worker
// Generated at: ${new Date().toISOString()}

// Make data available to the Worker scope
self.MEDICAL_TERMS_DATA = ${JSON.stringify(medicalTerms)};

self.FINANCIAL_TERMS_DATA = ${JSON.stringify(financialTerms)};

self.ORGANIZATIONS_DATA = ${JSON.stringify(organizationTerms)};

self.OCCUPATIONS_DATA = ${JSON.stringify(occupationTerms)};

// Signal that worker data is ready
if (typeof self !== 'undefined') {
  self.WORKER_DATA_READY = true;
  console.log('[Worker] Data bundle loaded successfully');
}
`;

// Write the bundle file
const outputPath = path.join(__dirname, '..', 'worker-data-bundle.js');
fs.writeFileSync(outputPath, bundle);

const stats = fs.statSync(outputPath);
const sizeKB = (stats.size / 1024).toFixed(2);

console.log(`\n[build-worker-bundle] ✓ Bundle generated successfully`);
console.log(`  Output: worker-data-bundle.js`);
console.log(`  Size: ${sizeKB} KB`);
console.log(`  Total items: ${
  medicalTerms.length +
  financialTerms.length +
  organizationTerms.length +
  occupationTerms.length
} terms`);
